  "prediction_basis_card_ids": ["C01","C02","C06","C17","C22","C27","C54","C56","C57","C60"],
  "claims": [
    {
      "claim": "Samidorphan, the closest measured morphinan analog in the visible records, has an absolute oral bioavailability of about 69% (mean 68.6%, range 60.3–82.6%) after a single 2 mg oral dose in healthy volunteers, well above the 20% threshold; the query is an oxycodone-type 4,5-epoxymorphinan-6-one in the same opioid scaffold family.",
      "card_ids": ["C01","C02","C06","C17"]
    },
    {
      "claim": "L2 records describe samidorphan as having much greater or increased oral bioavailability compared with naltrexone, consistent with the quantitative F value and supporting transfer of high-F evidence to the morphinan scaffold.",
      "card_ids": ["C22","C27"]
    },
    {
      "claim": "L5 gut-wall/intestinal permeability records for related morphinans show high Caco-2/MDCK permeability and rapid small-intestinal absorption (morphine transported much faster than mannitol/PEG4000; the M03 morphinan GA2-50 permeability higher than propranolol), with no evidence of an efflux-limited barrier for this scaffold.",
      "card_ids": ["C54","C56","C57","C60"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C54","C56","C57","C60"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is present in the visible records; the decision relies on a structurally related morphinan (samidorphan), related morphinan permeability records, and the physicochemical prior.",
    "Samidorphan differs from the query in N-substituent and aromatic substituents, and morphine/codeine differ at C6 and C7-C8; transfer is not exact.",
    "No query-specific gut-wall efflux or intestinal metabolism data are available; L5 records are for related or unrelated molecules.",
    "No formulation-specific, dose-ranging, or condition-matched data for the query are available in the visible records."
  ],
  "decision_summary": "Keep high (F >= 20%): the query is an oxycodone-type 4,5-epoxymorphinan-6-one with a favorable physicochemical prior; the closest measured morphinan analog samidorphan has absolute oral bioavailability ~69%, and L5 gut-wall/intestinal permeability records for related morphinans show high permeability and rapid intestinal absorption with no efflux-limited barrier. No visible record provides affirmative evidence for F < 20%; confidence remains moderate because no direct query F measurement is present."
}

